#if !defined(SPIRAL_MATRIX_H)
#define SPIRAL_MATRIX_H

#include <cstdint>
#include <vector>

namespace spiral_matrix {

std::vector<std::vector<uint32_t>> spiral_matrix(uint32_t size);

}  // namespace spiral_matrix

#endif  // SPIRAL_MATRIX_H

#include "spiral_matrix.h"

namespace spiral_matrix {

std::vector<std::vector<uint32_t>> spiral_matrix(uint32_t size) {
    std::vector<std::vector<uint32_t>> matrix(size, std::vector<uint32_t>(size, 0));

    // Boundaries of the current ring.
    uint32_t top = 0;
    uint32_t bottom = size;
    uint32_t left = 0;
    uint32_t right = size;

    uint32_t value = 1;
    uint32_t const total = size * size;

    while (value <= total) {
        // Traverse right along the top row.
        for (uint32_t col = left; col < right && value <= total; ++col)
            matrix[top][col] = value++;
        ++top;

        // Traverse down along the right column.
        for (uint32_t row = top; row < bottom && value <= total; ++row)
            matrix[row][right - 1] = value++;
        --right;

        // Traverse left along the bottom row.
        for (uint32_t col = right; col > left && value <= total; --col)
            matrix[bottom - 1][col - 1] = value++;
        --bottom;

        // Traverse up along the left column.
        for (uint32_t row = bottom; row > top && value <= total; --row)
            matrix[row - 1][left] = value++;
        ++left;
    }

    return matrix;
}

}  // namespace spiral_matrix
